import test from 'node:test'
import assert from 'node:assert/strict'
import { createSeed } from '../src/seed.js'
const storage=new Map()
globalThis.localStorage={getItem:key=>storage.get(key)||null,setItem:(key,value)=>storage.set(key,value)}
const model=await import('../src/model.js')
const {state,ui,login,changePassword,activate,rebind,resetPassword,saveDemo,STORAGE_KEY}=model
function reset(){Object.assign(state,createSeed());ui.fault='none';ui.busy=false;storage.clear()}
test('飞书与密码演示进入同一账号，人数不增加',async()=>{reset();const count=state.employees.length;await login('e1','feishu');const a=model.currentUser.value.accountId;await login('e1','password');assert.equal(model.currentUser.value.accountId,a);assert.equal(state.employees.length,count);assert.equal(JSON.parse(storage.get(STORAGE_KEY)).session,null)})
test('未开通、未绑定、停用均拒绝相应登录',async()=>{reset();assert.equal((await login('e3','feishu')).ok,false);assert.equal((await login('e4','password')).ok,false);state.employees.find(e=>e.id==='e1').bound=false;assert.equal((await login('e1','feishu')).ok,false);assert.equal((await login('e1','password')).ok,true)})
test('受控开通先核验，首次密码必须进入改密阶段',async()=>{reset();assert.equal((await activate('e3')).ok,false);state.employees.find(e=>e.id==='e3').checked=true;assert.equal((await activate('e3')).ok,true);assert.equal((await login('e3','password')).firstPassword,true);assert.equal(state.session.phase,'first-password');await changePassword('e3');assert.equal(state.session.phase,'active');assert.equal(state.employees.find(e=>e.id==='e3').firstPassword,false)})
test('管理员重置只恢复演示首次改密标记，不存储现用密码',async()=>{reset();await resetPassword('e1');assert.equal((await login('e1','password')).firstPassword,true);assert.equal(state.employees.some(e=>'password' in e),false)})
test('换绑冲突拒绝，成功仍保留原员工和账号',async()=>{reset();await login('e1','password');const account=state.employees.find(e=>e.id==='e1').accountId;assert.equal((await rebind('e1','demo-feishu-e2')).ok,false);assert.equal(state.employees.find(e=>e.id==='e1').feishuId,'demo-feishu-e1');assert.equal((await rebind('e1','demo-feishu-e1-new')).ok,true);assert.equal(state.employees.find(e=>e.id==='e1').accountId,account)})
test('保存失败或冲突不留改动/成功日志，随后可正常重试',async()=>{for(const fault of ['save-failure','conflict']){reset();const before=JSON.stringify(state);ui.fault=fault;assert.equal((await saveDemo('失败操作',()=>{state.employees.find(e=>e.id==='e3').checked=true})).ok,false);assert.equal(JSON.stringify(state),before);ui.fault='none';assert.equal((await saveDemo('重试核验',()=>{state.employees.find(e=>e.id==='e3').checked=true})).ok,true);assert.equal(state.employees.find(e=>e.id==='e3').checked,true)}})
test('飞书服务失败可使用同账号的密码备用入口',async()=>{reset();ui.fault='service-failure';assert.equal((await login('e1','feishu')).ok,false);assert.equal((await login('e1','password')).ok,true)})

test('企业首次开户复用Employee，重试不重复创建或再展示口令',async()=>{reset();const n=state.employees.length;const first=await model.enterpriseLogin('first-linked');assert.equal(first.ok,true);assert.ok(first.temporaryPassword);assert.equal(state.session,null);assert.equal(state.employees.length,n);assert.equal(state.employees.find(e=>e.id==='e3').employeeId,'DEMO-EMP-00103');const second=await model.enterpriseLogin('first-linked');assert.equal(second.reused,true);assert.equal(second.temporaryPassword,undefined);assert.equal(storage.get(STORAGE_KEY).includes(first.temporaryPassword),false)})
test('未关联Employee企业账号不伪造员工，明确关联不增人或增户',async()=>{reset();const count=state.employees.length;const result=await model.enterpriseLogin('first-unlinked');assert.equal(result.pendingEmployee,true);assert.equal(state.employees.length,count);assert.equal(model.allSubjects.value.find(e=>e.id===result.employeeId).employeeId,null);state.employees.find(e=>e.id==='e3').checked=true;assert.equal((await model.linkExistingAccount('e3','demo.user.zhoulan@example.invalid')).ok,true);assert.equal(state.employees.length,count);assert.equal(state.nonEmployeeAccounts.some(e=>e.id==='u-zhoulan'),false);assert.equal(state.employees.find(e=>e.id==='e3').accountId,'demo.user.zhoulan@example.invalid');const repeat=await model.enterpriseLogin('first-unlinked');assert.equal(repeat.employeeId,'e3');assert.equal(repeat.reused,true);assert.equal(repeat.temporaryPassword,undefined);assert.equal(model.allSubjects.value.filter(e=>e.accountId==='demo.user.zhoulan@example.invalid').length,1)})
test('非本企业/冲突拒绝不改名册；预建绑定必须正确归属证明',async()=>{reset();const before=JSON.stringify(state);for(const s of ['foreign','conflict'])assert.equal((await model.enterpriseLogin(s)).ok,false);assert.equal(JSON.stringify(state),before);const result=await model.enterpriseLogin('precreated');assert.equal(result.needsVerification,true);assert.equal((await model.verifyPrecreatedBinding('e5',{})).ok,false);const account=state.employees.find(e=>e.id==='e5').accountId;assert.equal((await model.verifyPrecreatedBinding('e5',{identityVerified:true,mfaVerified:true})).ok,true);assert.equal(state.employees.find(e=>e.id==='e5').accountId,account);const repeat=await model.enterpriseLogin('precreated');assert.equal(repeat.reused,true);assert.equal(repeat.needsVerification,undefined);assert.equal(repeat.temporaryPassword,undefined)})
test('管理员会话不能代选中员工执行本人改密/换绑',async()=>{reset();await login('admin','password');assert.equal((await changePassword('e1')).ok,false);assert.equal((await rebind('e1','demo-feishu-not-owner')).ok,false)})
